--
-- Table structure for table `tblcheque_management`
--

CREATE TABLE `tblcheque_management` (
  `id` int(11) NOT NULL,
  `cheque_type` enum('incoming','outgoing') NOT NULL DEFAULT 'incoming' COMMENT 'incoming=customer, outgoing=vendor',
  `direction` enum('customer','vendor') NOT NULL DEFAULT 'customer',
  `source_type` varchar(50) NOT NULL DEFAULT 'manual' COMMENT 'pur_invoice_payment|sales_payment|expense|manual',
  `source_id` int(11) DEFAULT NULL,
  `cheque_number` varchar(100) NOT NULL DEFAULT '',
  `cheque_bank_name` varchar(200) DEFAULT NULL,
  `cheque_date` date DEFAULT NULL,
  `deposit_date` date DEFAULT NULL,
  `cleared_date` date DEFAULT NULL,
  `bounce_date` date DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `currency` varchar(10) DEFAULT NULL,
  `rel_id` int(11) DEFAULT NULL,
  `rel_name` varchar(300) DEFAULT NULL,
  `rel_bank` varchar(200) DEFAULT NULL,
  `invoice_ref` varchar(200) DEFAULT NULL,
  `transaction_id` varchar(200) DEFAULT NULL,
  `deposit_slip_no` varchar(100) DEFAULT NULL,
  `batch_ref` varchar(100) DEFAULT NULL,
  `bank_account_id` int(11) DEFAULT NULL COMMENT 'FK to acc_accounts',
  `status` tinyint(2) NOT NULL DEFAULT 1,
  `is_pdc` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Post-Dated Cheque',
  `bounce_reason` varchar(300) DEFAULT NULL,
  `bounce_charges` decimal(15,2) DEFAULT 0.00,
  `maker_id` int(11) DEFAULT NULL,
  `checker_id` int(11) DEFAULT NULL,
  `approver_id` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `approval_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=pending,1=approved,2=rejected',
  `cheque_attachment` varchar(500) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

