INSERT INTO `tblpur_terms` (`id`, `name`, `content`, `created_by`, `datecreated`) VALUES
(1, 'Terms 1', '<ul>\r\n<li><span>All purchase requests must be submitted with complete and accurate details, including item description, quantity, specifications, and justification for purchase.</span></li>\r\n<li><span>Submission of a purchase request does not constitute approval or commitment to procure the requested items.</span></li>\r\n<li><span>All requests are subject to review, budget availability, and approval from the authorized approving authority.</span></li>\r\n<li><span>Any incomplete or unclear purchase requests may be returned for clarification or correction.</span></li>\r\n<li><span>Procurement will be processed only after obtaining all required approvals as per company policy.</span></li>\r\n<li><span>The requester is responsible for ensuring that the requested items are necessary for official business purposes.</span></li>\r\n<li><span>Any urgent purchase requests must clearly specify the reason for urgency and may require additional approval.</span></li>\r\n<li><span>Changes or cancellations to approved purchase requests must be communicated immediately to the procurement team.</span></li>\r\n<li><span>Delivery timelines are subject to vendor availability and procurement processing timelines.</span></li>\r\n<li><span>The company reserves the right to reject, modify, or defer any purchase request based on operational requirements or budget constraints.</span></li>\r\n<li><span>All purchased items must comply with organizational procurement standards and applicable policies.</span></li>\r\n<li><span>The requester acknowledges responsibility for verifying the delivered items and reporting any discrepancies promptly.</span></li>\r\n</ul>', 1, '2026-05-13 11:50:21'),
(2, 'Terms 2', '<ul>\r\n<li><span>All purchase requests must be submitted with complete and accurate details, including item description, quantity, specifications, and justification for purchase.</span></li>\r\n<li><span>Submission of a purchase request does not constitute approval or commitment to procure the requested items.</span></li>\r\n<li><span>All requests are subject to review, budget availability, and approval from the authorized approving authority.</span></li>\r\n<li><span>Any incomplete or unclear purchase requests may be returned for clarification or correction.</span></li>\r\n<li><span>Procurement will be processed only after obtaining all required approvals as per company policy.</span><span></span></li>\r\n</ul>', 1, '2026-05-13 11:50:42');

